/**
 * tests/test-m1-2-challenger-streaming.js
 * 
 * EMPIRICAL ADVERSARIAL CHALLENGER TEST SUITE: MILESTONE 1 - INSTANCE 2
 * Streaming Proxy, Manifest Rewriting, HTTP 206 Partial Content & Memory Stress
 * 
 * Tests:
 * 1. Service Lifecycle & Clean Localhost HTTP Binding (127.0.0.1:8088)
 * 2. Real TMDB 550 stream resolution via crush.wasm and AES-256-GCM
 * 3. Master M3U8 manifest URL rewriting without URI corruption
 * 4. Manifest rewriting idempotency and roundtrip stability
 * 5. Variant playlist URL rewriting, media segments, and #EXT-X-MAP
 * 6. Initialization Segment (init.png) & ISO BMFF 'ftyp' box validation
 * 7. Initialization Segment out-of-bounds range request handling (HTTP 416)
 * 8. Media Segment HTTP 206 Partial Content Slice 1 (bytes=0-1023)
 * 9. Media Segment HTTP 206 Partial Content Slice 2 (bytes=1024-2047)
 * 10. Slicing contiguity oracle: slice1 + slice2 === combined (bytes=0-2047) (bit-for-bit)
 * 11. Outbound headers verification (Origin, Referer, User-Agent, Range) via local mock upstream
 * 12. Real Upstream Lightspeed CDN Origin enforcement oracle (404 without vs 200 with)
 * 13. High-volume concurrent streaming & RSS memory budget verification (<50 MB on TV Node 12)
 * 14. Adversarial boundary & error handling (missing params, disallowed protocol, 404 upstream, HEAD)
 * 15. Client disconnect & socket abort cleanup
 */

'use strict';

const http = require('http');
const https = require('https');
const { spawn } = require('child_process');
const path = require('path');
const fs = require('fs');
const { URL } = require('url');

const TEST_PORT = 8088;
const TEST_HOST = '127.0.0.1';
const SERVICE_DIR = path.resolve(__dirname, '..', 'poc', 'service');
const SERVICE_ENTRY = path.join(SERVICE_DIR, 'index.js');

const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  gray: '\x1b[90m',
  magenta: '\x1b[35m'
};

let serverProcess = null;
let streamMasterUrl = null;
let variantProxyUrl = null;
let initSegmentProxyUrl = null;
let mediaSegmentProxyUrl = null;

let totalTests = 0;
let passedTests = 0;
let failedTests = 0;
const results = [];

function assert(condition, message) {
  if (!condition) {
    throw new Error(message || 'Assertion failed');
  }
}

function request(options, body) {
  return new Promise(function (resolve, reject) {
    const isHttps = options.protocol === 'https:';
    const client = isHttps ? https : http;

    const reqOpts = Object.assign({}, options);
    reqOpts.headers = Object.assign({}, options.headers || {});

    if (body && !reqOpts.headers['Content-Length'] && !reqOpts.headers['content-length']) {
      reqOpts.headers['Content-Length'] = Buffer.isBuffer(body) ? body.length : Buffer.byteLength(body);
    }

    const req = client.request(reqOpts, function (res) {
      const chunks = [];
      res.on('data', function (c) { chunks.push(c); });
      res.on('end', function () {
        const rawBuffer = Buffer.concat(chunks);
        let text = null;
        let json = null;
        try {
          text = rawBuffer.toString('utf8');
          json = JSON.parse(text);
        } catch (_) {}
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          buffer: rawBuffer,
          text: text,
          json: json
        });
      });
    });

    req.on('error', reject);
    const timeout = options.timeout || 30000;
    req.setTimeout(timeout, function () {
      req.abort();
      reject(new Error('Request timed out after ' + timeout + 'ms'));
    });

    if (body) req.write(body);
    req.end();
  });
}

async function runTest(name, fn) {
  totalTests++;
  const start = Date.now();
  process.stdout.write('  [' + totalTests + '] ' + name + ' ... ');
  try {
    await fn();
    const duration = Date.now() - start;
    console.log(C.green + '✔ PASS' + C.reset + ' (' + duration + 'ms)');
    passedTests++;
    results.push({ name: name, passed: true, duration: duration });
  } catch (err) {
    const duration = Date.now() - start;
    console.log(C.red + '✖ FAIL' + C.reset + ' (' + duration + 'ms)');
    console.error(C.red + '      ' + err.message + C.reset);
    if (err.stack && process.env.VERBOSE) {
      console.error(C.gray + err.stack + C.reset);
    }
    failedTests++;
    results.push({ name: name, passed: false, duration: duration, error: err.message });
  }
}

function waitForHealth(port, maxWaitMs) {
  const start = Date.now();
  return new Promise(function (resolve) {
    function check() {
      if (Date.now() - start >= maxWaitMs) return resolve(false);
      request({
        hostname: TEST_HOST,
        port: port,
        path: '/health',
        method: 'GET',
        timeout: 800
      })
        .then(function (res) {
          if (res.statusCode === 200 && res.json && res.json.status === 'ok' && res.json.mode === 'on-device-service') {
            resolve(true);
          } else {
            setTimeout(check, 100);
          }
        })
        .catch(function () {
          setTimeout(check, 100);
        });
    }
    check();
  });
}

