  // ---------------------------------------------------------------------------
  await runTest('TC 15: Client Disconnect & Socket Abort Cleanup', function () {
    return new Promise(function (resolve, reject) {
      assert(mediaSegmentProxyUrl, 'Prerequisite failed: mediaSegmentProxyUrl not resolved');
      const segmentPath = mediaSegmentProxyUrl.replace('http://' + TEST_HOST + ':' + TEST_PORT, '');

